 ('bas', 'word', 'dbfc06f9-abcf-50d3-abb6-faee5fc75427', 1, 'noun', 'en', 'bass (instrument or voice)', 'Han spiller bas i et band.', 'He plays bass in a band.'), ('lokalsamfund', 'word', '806947ac-3c4e-5e98-a3f6-a890bbfe26d9', 1, 'noun', 'et', 'local community', 'Lokalsamfundet støttede projektet.', 'The local community supported the project.'), ('sammensætning', 'word', 'b8f36700-5c88-5d4b-b2ad-169f30205ec5', 1, 'noun', 'en', 'composition, makeup', 'Holdets sammensætning ændrede sig.', 'The team''s composition changed.'), ('drøftelse', 'word', 'efeacd84-c4ad-53ff-8c9c-4a5a76b80103', 1, 'noun', 'en', 'discussion', 'Sagen var under drøftelse i timevis.', 'The matter was under discussion for hours.'), ('berygtet', 'word', '44960904-da81-5597-9796-d0caa22868a3', 1, 'adjective', null, 'notorious', 'Han er berygtet for sin dårlige opførsel.', 'He is notorious for his bad behavior.'), ('terrasse', 'word', '4b8487ed-d7e7-53e4-8c53-438f034fb8d8', 1, 'noun', 'en', 'terrace', 'Vi spiste morgenmad på terrassen.', 'We had breakfast on the terrace.'), ('selvstyre', 'word', '6672fdd5-203d-5754-a925-62ba324fb24c', 1, 'noun', 'et', 'self-government, autonomy', 'Grønland har hjemmestyre og selvstyre.', 'Greenland has home rule and self-government.'), ('kode', 'word', 'cd5d1d99-97af-59c9-ac18-782c5697ec7e', 1, 'noun', 'en', 'code', 'Han glemte koden til døren.', 'He forgot the code for the door.'), ('sammenhængende', 'word', 'fe7c6107-91d2-5d2b-a629-a9d43d41b699', 1, 'adjective', null, 'coherent', 'Hun holdt en sammenhængende tale.', 'She gave a coherent speech.'), ('fremvise', 'word', '98b536e6-388f-5ff2-bbe1-368381de8900', 1, 'verb', null, 'to present, show', 'Han skal fremvise sit pas.', 'He must present his passport.'), ('statistisk', 'word', '78966fa6-24eb-5ef4-93bc-995a37ff7b58', 1, 'adjective', null, 'statistical', 'Det er en statistisk usikkerhed.', 'It is a statistical uncertainty.'), ('pumpe', 'word', '04d5a339-0214-58df-9d07-4a4fd68017c7', 1, 'verb', null, 'to pump', 'Han