334ff9f3', 1, 'adverb', null, 'whereby', 'De ændrede loven, hvorved processen blev lettere.', 'They changed the law, whereby the process became easier.'), ('fedt', 'word', '91bc5b4d-95d8-59c7-9d49-9f2aa59adebc', 1, 'noun', 'et', 'fat, grease', 'Kokken brugte fedt til stegningen.', 'The cook used fat for frying.'), ('magthaver', 'word', 'cbc04e1d-1183-575a-932a-12862a63d4f8', 1, 'noun', 'en', 'power holder, ruler', 'Folket protesterede mod magthaverne.', 'The people protested against those in power.'), ('civilisation', 'word', 'ca153784-6518-5722-8614-9ddea3238110', 1, 'noun', 'en', 'civilization', 'De studerede den gamle egyptiske civilisation.', 'They studied ancient Egyptian civilization.'), ('korn', 'word', '4b1a1129-a784-579a-9ee3-97e614a2bc7d', 1, 'noun', 'et', 'grain', 'Bønderne høstede korn i august.', 'The farmers harvested grain in August.'), ('mirakel', 'word', '14630462-8fa6-5bbb-93ec-6119b7213179', 1, 'noun', 'et', 'miracle', 'Det var et sandt mirakel, at han overlevede.', 'It was a true miracle that he survived.'), ('forebyggelse', 'word', '2d5f3796-41da-510e-9d1f-ead947a6a912', 1, 'noun', 'en', 'prevention', 'Forebyggelse af sygdom er vigtig.', 'Prevention of disease is important.'), ('kaotisk', 'word', '55e14333-6811-5761-a592-f02ce0644ac4', 1, 'adjective', null, 'chaotic', 'Trafikken var kaotisk i morges.', 'Traffic was chaotic this morning.'), ('beordre', 'word', '63e96193-4ccd-5b7c-9cc0-0801ec3bfd05', 1, 'verb', null, 'to order, command', 'Officeren beordrede soldaterne til at trække sig.', 'The officer ordered the soldiers to withdraw.'), ('beskidt', 'word', 'fc0c2742-0654-584e-8831-820c9c5368bf', 1, 'adjective', null, 'dirty', 'Hans hænder var beskidte efter arbejdet.', 'His hands were dirty after the work.'), ('efterforske', 'word', 'b1fd824b-92fa-57dd-9ab6-5a3409553f18', 1, 'verb', null, 'to investigate', 'Politiet efterforsker sagen grundigt.', 'The police are thoroughly investigating the case.'), ('filosofisk', 'word', 'a40d8b69-755c-5666-9100-2ca14d9b9736', 1, 'adjective', null, 'philosophical', 'De førte en filosofisk samtale.', 'They had a philosophical conversation.'), ('månen', 'word', '8ef4e862-33d3-5653-bb4e-2622cec44b06', 1, 'noun', null, 'moon', 'Månen skinnede klart på himlen.', 'The moon shone brightly in the sky.'), ('sild', 'word', 'd718fce7-dcf3-530d-ac88-bcd6b26e3067', 1, 'noun', 'en', 'herring', 'Vi spiste sild med rugbrød.', 'We ate herring with rye bread.'), ('hektisk', 'word', '08b71abc-80ce-5f84-82b4-238bc490de28', 1, 'adjective', null, 'hectic', 'Det var en hektisk dag på arbejdet.', 'It was a hectic day at work.'), ('efteruddannelse', 'word', '8ed5bde3-60e2-5051-ac03-319bc2bfd72d', 1, 'noun', 'en', 'further education, professional training', 'Hun tog en efteruddannelse i ledelse.', 'She took further education in management.'), ('sejlads', 'word', '9bcbc84a-ddc0-5b78-b373-35cb7b49f2ce', 1, 'noun', 'en', 'sailing, navigation', 'De nød en rolig sejlads på fjorden.', 'They enjoyed a calm sail on the fjord.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
